CASES = tuple(CORPUS)


def build(dest):
    """在 dest 里生成整套回归输入：5 篇合成稿 + 封面/正文图 + 过小图。返回 dest。"""
    for sub in ("images", "fixtures"):
        os.makedirs(os.path.join(dest, sub), exist_ok=True)
    for name, spec in CORPUS.items():
        with open(os.path.join(dest, name + ".md"), "w", encoding="utf-8") as f:
            f.write(spec["md"])
    for rel, blob in (("images/cover.jpg", jpeg("cover.jpg")),
                      ("images/fig.jpg", jpeg("fig.jpg")),
                      ("fixtures/tiny.png", png(*TINY))):
        with open(os.path.join(dest, rel.replace("/", os.sep)), "wb") as f:
            f.write(blob)
    return dest


if __name__ == "__main__":
    import sys
    import tempfile
    d = build(sys.argv[1] if len(sys.argv) > 1 else tempfile.mkdtemp(prefix="wechat-fixtures-"))
    print(d)
